with d as (select value r from jsonb_array_elements($q$[{"notes":["Use sashimi-grade or very fresh crab meat if available; tinned crab in brine works too.","White pepper, not black, keeps the soup's refined appearance, no dark specks.","Don't let the broth boil hard when pouring the egg white, or it will scramble into lumps instead of forming ribbons.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"e5c80f0f-29e0-4838-a20b-f0ad1cb10357"},{"notes":["Make the remoulade up to 3 days ahead and keep it in the fridge.","Use really good-quality roast beef sliced thin from the deli counter, it makes all the difference.","Assemble the smørrebrød just before serving so the bread stays crisp and the onions don't soften too much.","Food safety: Steaks and roasting cuts of beef or lamb can be served pink: about 60°C in the centre is medium-rare, 70°C is well done."],"steps":[{"text":"Make the remoulade: whisk together mayonnaise, Dijon mustard and wholegrain mustard until smooth. Fold in the capers and pickled gherkin. Add lemon juice and season with salt and pepper. Taste and adjust the mustard or lemon if needed."},{"text":"Lightly butter each slice of bread, spreading it all the way to the edges."},{"text":"Lay the roast beef slices on top of the butter in a slightly overlapping layer, until the bread is fully covered and the beef is soft and draped."},{"text":"Spoon remoulade generously over the beef."},{"text":"Top with pickled cucumber slices and a handful of crispy fried onions."},{"text":"Garnish with a small sprig of fresh parsley and serve immediately."}],"id":"6a54fad5-86c8-4094-8b45-8b92f42dc985"},{"notes":["The 'tarik' (pull) is what creates the signature smooth texture and foam. At home, a careful pour from height into the glass works; the mamak masters pour between two vessels for even more drama.","Use a strong black tea, English Breakfast or Assam works perfectly. The tea needs to be robust enough to stand up to the milk.","Drink it straight away while hot and foamy; it's not the same when it cools down."],"steps":[{"text":"Boil the water in a kettle or small saucepan until it reaches a rolling boil with large bubbles."},{"text":"Place the black tea leaves in a small pot or teapot. Pour the boiling water over the leaves and let steep for 2–3 minutes until the tea is very strong and dark."},{"text":"Strain the tea into a large jug, leaving behind the leaves (or remove the tea bags)."},{"text":"Pour the condensed milk and evaporated milk into two glasses or cups."},{"text":"Carefully pour the hot tea into each glass over the milk, stirring well to combine. If you're feeling brave, pour the tea from a height to create the signature foam and mix."},{"text":"Taste and add a pinch of salt if you like. Serve hot, and drink while the foam is still there."}],"id":"07746180-71bf-4e2b-9c3e-f182e0787358"},{"notes":["The pork can marinate for up to 24 hours, the longer, the better the flavour.","If you can't find achiote paste, use the annatto seed swap, or swap in 1 tbsp smoked paprika plus ½ tsp ground turmeric for a different but still delicious flavour.","Leftover cooked pork keeps in the fridge for 3 days and makes a great burrito filling.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"56f5b837-093e-4de1-90df-ba4061e54da4"},{"notes":["Nopales prep: Remove the spines carefully with a sharp knife or peeler, then trim the base. If you can't find fresh nopales, jarred or tinned ones work, just drain and rinse before use, and reduce simmering time to 5–8 minutes.","This soup keeps well in the fridge for 3 days and can be frozen for up to a month."],"steps":[{"text":"Heat olive oil in a large pot over medium heat. Add the quartered onion and crushed garlic, cooking gently until softened and fragrant, about 4 minutes."},{"text":"Add the diced nopales to the pot, stirring to coat in the oil. Cook for 3–4 minutes; the nopales will release a slight mucilage, which is normal and helps thicken the broth."},{"text":"Pour in the tinned tomatoes and vegetable stock, breaking up the tomatoes gently. Bring to a simmer until the soup is bubbling gently."},{"text":"Simmer, uncovered, for 15–18 minutes until the nopales are tender and the broth has developed flavour. Taste and season with salt and black pepper."},{"text":"Ladle into bowls. Serve hot, scattered with fresh coriander and a lime wedge on the side."}],"id":"8716e77f-f36b-4296-a7c2-fed8af1249d7"},{"notes":["Make these just before serving, they're best eaten warm straight off the tawa.","Pair with sarson da saag, a dollop of yoghurt and sliced onion."],"steps":[{"text":"Mix the cornmeal, green chilli and salt in a large bowl."},{"text":"Pour in the warm water slowly, stirring with your fingers until you have a soft, sticky dough that just comes together. It should feel wetter than wheat dough, don't try to knead it smooth."},{"text":"Heat a cast iron tawa or non-stick frying pan over medium-high heat until a drop of water sizzles and disappears in a second."},{"text":"Wet your hands with water. Take a golf-ball-sized piece of dough and flatten it between your palms into a rough circle about 5 mm thick. It won't be perfect and it doesn't need to be."},{"text":"Carefully lay it on the hot tawa and cook for 1 to 2 minutes, until the bottom is pale golden and starting to blister. It will look fragile but it's not."},{"text":"Flip gently and cook the other side for another 1 to 2 minutes until golden and speckled brown. The roti will stay soft and slightly crumbly."},{"text":"Transfer to a plate and dot with a tiny bit of ghee or butter. Serve hot, while they're still warm enough to tear easily."}],"id":"c93fd96f-ebe6-46b7-9be1-08b40063f8f2"},{"notes":["Make it a day ahead; the flavour deepens as it sits.","Use sterilised jars, run them through the dishwasher on a hot cycle or boil them for 10 minutes.","Serve as a side to mezze, with fresh bread, or alongside grilled vegetables and legumes."],"id":"10623218-2acb-4a1f-bf77-60873b9ceed3"},{"notes":["Serve with steamed white rice, taro or fresh soda bread to soak up the coconut broth.","You can use any firm white fish: barramundi, snapper, flathead or basa all work well.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oil in a large pan over medium heat. Add the onion and cook, stirring, until soft and golden, about 5 minutes."},{"text":"Add the garlic and stir for 1 minute until fragrant."},{"text":"Pour in the coconut milk and crushed tomatoes. Stir to combine and bring to a gentle simmer until the sauce is bubbling lightly."},{"text":"Add the silverbeet stems and cook for 3 minutes. Then add the silverbeet leaves and stir through."},{"text":"Gently add the fish chunks to the pan, stirring carefully to distribute them evenly. Simmer for 10 to 12 minutes, until the fish is cooked through and flakes easily."},{"text":"Season with salt and black pepper to taste. Serve hot with rice or taro."}],"id":"b2f82d01-347e-4774-8ff9-5f4631c3c46c"},{"notes":["Make ahead: soak the rice overnight, then steam and serve fresh.","Keep the rice warm: wrapped in a damp cloth in the bamboo basket for up to an hour.","No sticky-rice basket? A covered bamboo steamer or any covered pot works fine, just keep it warm and wrapped."],"id":"b5bb9a84-5574-4d35-8f3f-ff7a5706ef32"},{"notes":["The meringue base can be made up to 2 days ahead and kept in an airtight container.","Quandongs are tart stone fruit sourced locally in Central Australia; if unavailable outside the region, use fresh or lightly stewed stone fruit like peaches, nectarines or apricots.","Assemble just before serving so the meringue stays crisp.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"53d53b85-205c-4d06-a172-3b48a3473d58"},{"notes":["Make ahead: boil potatoes the night before and keep in the fridge. The sauce also keeps for 2 days. Warm gently and serve at room temperature.","If you can't find ají amarillo paste, look for it in the Latin or South American aisle of your supermarket, or online. It's worth seeking out, it has a distinctive mild heat and fruity flavour unique to Peruvian cooking."],"id":"6e5e84c0-d201-47fd-8df4-ceb4e61b239b"},{"steps":[{"text":"Place the sliced daikon in a large bowl. Add 1 tbsp salt and toss gently but thoroughly until every slice is coated. Set a timer: salt the radish for exactly 20 minutes, this is crucial. The radish should release its water and become pliable but still crisp."},{"text":"While the radish salts, prepare the brine: dissolve 2 tbsp salt in 1 litre of cold water in a separate bowl. Stir in the fish sauce and sugar until dissolved. Taste and adjust the salt if needed, it should taste pleasantly salty, like a good broth."},{"text":"After 20 minutes, gently rinse the radish under cold running water, pressing softly to remove excess salt and liquid. Drain well in a colander for 2 minutes."},{"text":"Transfer the drained radish to a clean container or bowl. Add the gochugaru, garlic, ginger and spring onions, tossing gently to combine."},{"text":"Pour the cold brine over the vegetables until they are just covered. Press a piece of plastic wrap or a small plate onto the surface to keep everything submerged."},{"text":"Cover and refrigerate for at least 2 hours before serving. The nabak kimchi will taste good cold from the fridge and will keep for up to 2 weeks. The flavour deepens as it ferments; after 3–4 days in the fridge, it develops a gentle fizz and tang."}],"id":"3e64a42e-12e5-4bf2-b2e4-94fdd284389a"},{"steps":[{"text":"Pour the dashi into a small pot. Add soy sauce and mirin, and bring to a simmer over medium heat until small bubbles form at the edge and the mixture is fragrant. Keep it warm."},{"text":"Cut the chilled tofu into 4 cubes, patting them dry very gently with paper towel, moisture is the enemy of crispness."},{"text":"Put cornflour in a shallow dish and season lightly with salt. Coat each tofu cube gently on all sides."},{"text":"Heat a thin layer of neutral oil in a small frying pan over medium-high heat until it shimmers. It should be hot but not smoking."},{"text":"Carefully place the tofu cubes in the oil and cook for 3 to 4 minutes, turning once, until the outside is golden and crisp all over."},{"text":"Divide the hot dashi between two bowls. Gently place two tofu cubes into each bowl."},{"text":"Top with spring onion and ginger, and serve at once, while the dashi steams and the tofu still has its gentle warmth."}],"id":"79210637-96bb-4d1f-a023-1e33dd7e52ac"},{"steps":[{"text":"Heat the oil in a heavy-bottomed pot over medium heat. Add the rice and stir constantly until it turns pale golden and smells toasted, about 3 minutes."},{"text":"Add the onion halves and bay leaf, then pour in the chicken stock. Stir once, then bring to a boil until the stock is bubbling steadily."},{"text":"Once boiling, reduce the heat to low, cover with a tight-fitting lid, and cook without lifting the lid for 15 minutes, until the rice is tender and the liquid is absorbed."},{"text":"Remove from the heat and let it rest, covered, for 2 minutes. Remove the onion halves and bay leaf, fluff the rice with a fork, season with salt to taste, and serve."}],"id":"802272b1-634e-4c7c-b697-b26a75af773f"},{"notes":["Make it a day ahead. The flavour only gets better sitting in the fridge overnight.","Serve with crusty bread, mash, or over rice to soak up the gravy.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"ab787c22-d7c2-4c9c-a9b7-13552848f549"},{"notes":["Make ahead: Assemble the lumpia up to 4 hours ahead and refrigerate on a tray before frying. Fry just before serving.","Oil temperature is key, too cool and they'll be greasy; too hot and they'll burn. Use a thermometer or the wrapper test.","Serve with sweet chilli sauce, vinegar, or a quick dipping sauce made from soy sauce and a squeeze of lemon.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C. Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"b72be6bd-9e20-4c77-a5b9-e05a3b86357c"},{"notes":["Make ahead: marinate the chicken up to 4 hours. Fry it just before serving so it stays crispy.","The numbing heat comes from Sichuan peppercorn, the burn from dried chilies. Neither are mistakes, they're the point.","Serve with plain steamed rice or congee to cool your mouth between bites.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"id":"5d1dbf57-f48c-4ec0-982f-e892b40f9241"},{"notes":["Shiro keeps for 3 days in the fridge. Reheat gently with a splash of water or stock, stirring often.","Shiro is a classic Ethiopian fasting dish: vegan, filling and humble."],"id":"5a54d1d3-f594-43fd-88ae-081319639424"},{"notes":["Serve over jasmine rice. One batch feeds one person with rice.","Make ahead: the curry keeps in the fridge for 3 days and reheats gently on the stove.","Swap peanut butter for ground peanuts (2 tbsp) stirred in at the end if you prefer texture.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Heat oil in a wok or wide pan over medium-high heat until shimmering, about 1 minute."},{"text":"Add curry paste and cook, stirring, for 1 minute until fragrant."},{"text":"Add chicken and stir-fry until the edges turn opaque, about 3 minutes."},{"text":"Pour in coconut milk and bring to a simmer, stirring gently, until the sauce is bubbling lightly and thickens slightly."},{"text":"Add peanut butter, fish sauce and palm sugar. Stir until peanut butter dissolves, about 2 minutes."},{"text":"Tear in the makrut lime leaf and simmer for 5 minutes until chicken is cooked through (75°C inside) and sauce is thick and glossy."},{"text":"Taste and adjust fish sauce or palm sugar to balance salty and sweet."},{"text":"Serve in a bowl with jasmine rice, topped with fresh Thai basil and chilli if using."}],"id":"3cf345e7-eebd-46b0-aca7-67d6a440257d"},{"notes":["Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large pot over medium heat. Add the turmeric and crushed garlic, stirring for 30 seconds until fragrant and the oil turns golden yellow."},{"text":"Pour in the stock and coconut milk, stirring to combine. Bring to a simmer over medium-high heat until the broth is bubbling gently and steaming."},{"text":"Add the fish sauce and stir. Add the chicken slices and simmer gently for 8–10 minutes, stirring occasionally, until the chicken is cooked through."},{"text":"While the chicken cooks, bring a large pot of water to the boil. Add the noodles and cook according to packet directions until just tender. Drain well."},{"text":"Divide the noodles between two bowls. Ladle the hot broth and chicken over the top."},{"text":"Scatter the spring onions over each bowl. Serve with a lime wedge and fresh coriander on the side if you like. Squeeze the lime in before eating."}],"id":"76dc964f-0966-4f38-9b83-66915d26dd41"},{"notes":["Make it ahead: the curry tastes better the next day. Store in the fridge for up to 3 days, or freeze for a month.","Use whatever mushrooms you have, cremini, button, portobello all work. Firmer varieties hold their shape better in the long simmer."],"steps":[{"text":"Heat the oil in a large pot or deep pan over medium heat. Add the curry paste and cook, stirring, for 2 minutes until fragrant."},{"text":"Add the ginger and garlic, cook for another minute until fragrant, then pour in the coconut milk and stir well to combine."},{"text":"Add the mushrooms and stir to coat with the curry mixture. Cook for 5 minutes until they start to soften."},{"text":"Pour in the vegetable stock, tamarind paste and palm sugar. Stir until the sugar and tamarind dissolve, about 2 minutes."},{"text":"Bring to a gentle simmer and cook uncovered for 25–30 minutes, stirring occasionally, until the mushrooms are very tender and the curry has reduced and darkened. The sauce should coat the back of a spoon."},{"text":"Taste and adjust salt and sourness if needed. Serve hot with jasmine rice."}],"id":"bfd6329e-139c-4a01-b42a-116e34be6827"},{"diets":[],"notes":["Make them ahead: assemble the rolls, refrigerate up to 4 hours, then bake as directed.","The eggplants need to lose their water first – salt them well and don't rush this step.","For a vegetarian version, use a vegetarian hard cheese (made without animal rennet)."],"id":"43bf1c73-88de-460f-b224-b8c172c25ba4"},{"notes":["Make ahead: marinate the chicken overnight in the fridge for deeper flavour and better texture.","Leftovers: keeps in an airtight container in the fridge for 3 days; serve cold in bento or reheat gently.","Oil temperature matters: use a thermometer if you have one; too cool and it will be oily, too hot and the outside burns before the inside cooks.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Combine soy sauce, mirin, garlic, ginger and sesame oil in a bowl. Add the chicken pieces and toss to coat well. Cover and marinate in the fridge for at least 2 hours, preferably overnight."},{"text":"When ready to cook, remove the chicken from the marinade and place on paper towel. Pat dry thoroughly, this is important for crispiness. Reserve the marinade."},{"text":"Mix potato starch and plain flour together on a plate. Season the chicken pieces lightly with salt and white pepper, then coat each piece in the starch mixture, shaking off any excess."},{"text":"Heat neutral oil in a deep-sided pan or wok to 170°C. Working in batches so the pan isn't crowded, carefully lower the chicken into the oil."},{"text":"Fry for 8 to 10 minutes, turning halfway through, until the coating is golden and the thickest pieces are cooked through (75°C inside). Transfer to a paper towel to drain."},{"text":"Serve hot with lemon wedges and fresh coriander if you like. Any leftovers keep well cold in a bento box for the next day."}],"id":"8dd16d1b-296d-4f49-9a8e-4a763cfa1c24"},{"notes":["Make the filling up to a day ahead; store in the fridge. Assemble sambuusas up to 2 hours before frying.","If filo dries out as you work, cover the sheets with a damp tea towel.","Freeze uncooked sambuusas on a tray, then transfer to a container. Fry from frozen, adding a minute or two to the cooking time.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"58a47f13-1e17-4c48-9143-73818093fbf0"},{"notes":["Biscuits are best served warm from the oven. Leftovers can be split and toasted the next day.","For extra tender biscuits, chill the dough for 15 minutes before cutting and baking.","Make sure your butter and buttermilk are cold, this is what gives the biscuits their flaky layers."],"steps":[{"text":"Preheat oven to 200°C. Place a 25 cm cast-iron frying pan in the oven to heat."},{"text":"Whisk together flour, baking powder and salt in a large bowl. Add the cold butter cubes and use your fingertips to rub the mixture until it resembles coarse breadcrumbs with some pea-sized pieces of butter remaining."},{"text":"Make a well in the centre and pour in the cold buttermilk. Using a fork, gently mix until a shaggy dough just comes together, don't overwork it or the biscuits will be tough."},{"text":"Turn the dough out onto a lightly floured bench and gently pat it into a 2 cm thick round. Using a 7 cm biscuit cutter dipped in flour, cut out biscuits, pressing straight down without twisting."},{"text":"Carefully remove the hot frying pan from the oven and brush lightly with melted butter. Arrange biscuits in the pan, they should just touch each other."},{"text":"Brush the tops with a little more melted butter. Bake for 12–15 minutes, until golden brown on top and cooked through."},{"text":"Let cool in the pan for 2 minutes, then turn out onto a wire rack. Serve warm."}],"id":"179cacfb-8c92-43ab-92ad-d727e42127c7"},{"notes":["Use day-old or chilled rice, fresh hot rice gets mushy. If you only have hot rice, spread it on a plate to cool first.","Toast the Sichuan peppercorns in a dry pan for 1 minute before grinding for deeper flavour.","Leftovers keep in the fridge for 2 days and reheat well in a hot pan.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"7ba10ef1-daa2-49e8-89eb-a71f36afb946"},{"notes":["Maklouba keeps well in the fridge for up to 3 days. Reheat gently in a low oven wrapped in foil, or flash it in a hot pan to recrisp the bottom layer.","Use a non-stick or well-seasoned pot, this makes the flip much less stressful.","The spice blend is forgiving. If you don't have cardamom, add a pinch more cumin. If you don't have cinnamon, leave it out entirely."],"steps":[{"text":"Fry the eggplant slices in batches in hot oil until golden on both sides, about 4 minutes. Transfer to a plate lined with paper towel. This step is crucial, the eggplant will soften in the steam, so frying it first keeps its shape and flavour."},{"text":"In the same oil, fry the potato matchsticks in batches until just starting to turn golden, about 3 minutes. You want them still a bit firm because they'll cook further in the rice. Transfer to the paper towel plate."},{"text":"Fry the cauliflower florets until lightly golden, about 3 minutes. Set aside. You should have about 3 tablespoons of oil left in the pot; if not, add a little more."},{"text":"In the same pot, cook the sliced onions over medium heat, stirring, until soft and golden, about 8 minutes. Add the garlic and cook for 1 minute more until fragrant."},{"text":"Stir in the cumin, coriander, cardamom and cinnamon, cooking for 1 minute. You'll smell the spices bloom, this is when their flavour becomes most alive. Add the rice and stir to coat it in the spiced oil, cooking for 2 minutes."},{"text":"Layer the rice mixture back into the pot in this order: half the rice on the bottom, then the eggplant, potato and cauliflower mixed together, then the remaining rice on top. Press down gently to compact the layers. Pour the warm stock over carefully."},{"text":"Bring to a boil, then reduce heat to low. Cover with foil, then place the lid on top, the foil traps steam, which cooks the rice evenly. Cook for 20 minutes until the rice is tender and the stock is absorbed. Listen: when the liquid stops bubbling, you're done."},{"text":"Let it rest, covered, for 5 minutes. Run a thin knife around the edges of the pot to loosen it. Place a large platter over the pot, and in one confident motion, flip the pot onto the platter. Lift the pot away slowly. You should see a golden crust on top."},{"text":"Serve warm with generous dollops of Greek yoghurt and fresh parsley if you like. Eat it while the crust is still crispy."}],"id":"cc1d39fc-4f66-4032-885e-eefb12f755e9"},{"notes":["Fesenjan tastes better the next day. Make it ahead and reheat gently.","If you can't find pomegranate molasses, use equal parts pomegranate juice and lemon juice reduced in a pan until syrupy, or use a mix of pomegranate juice and balsamic vinegar.","Serve with tahdig, rice cooked until the bottom catches and caramelizes in a thin, crispy layer.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large, heavy pot over medium-high heat. Season the chicken generously with salt and pepper. Working in batches, brown the chicken skin-side down for 5 minutes, then turn and brown the other side for 3 minutes. Set aside."},{"text":"In the same pot, add the onion halves and cook, stirring occasionally, until they soften and colour, about 8 minutes. Add the tomato paste and cook for 1 minute, stirring."},{"text":"Stir in the walnuts, cinnamon and turmeric. Cook for 2 minutes until fragrant."},{"text":"Pour in the pomegranate juice and pomegranate molasses, scraping up any brown bits from the bottom of the pot. Return the chicken to the pot, skin-side up. Bring to a simmer until the sauce is bubbling gently and starting to thicken."},{"text":"Cover and cook on low heat for 50–60 minutes, until the chicken is tender and cooked through and the sauce has deepened in colour and thickened slightly. Taste and adjust the salt, pepper, and balance of sweet and sour as needed."},{"text":"Remove the onion halves. Serve over rice, with fresh coriander if you like it."}],"id":"fccf0bf5-45fd-479e-8151-7d2ab6c16e94"},{"notes":["Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Heat the oil in a large heavy-bottomed pot over medium heat. Add the flour and stir constantly for 8 to 10 minutes, until the roux is deep golden brown, this is the foundation of everything. Don't rush it; if it starts to burn, pull it off the heat for a moment."},{"text":"Add the onion, capsicum, and celery to the roux. Stir well and cook for about 5 minutes, until the vegetables soften and release their flavour. This is the holy trinity, cher."},{"text":"Push the vegetables to the side, add the sausage, and let it sear for 2 to 3 minutes. Stir in the garlic, cayenne, paprika, thyme, and oregano, cooking for 1 more minute until fragrant."},{"text":"Pour in the crushed tomatoes and chicken stock. Scrape the bottom of the pot to loosen any browned bits. Bring to a gentle boil until bubbling, then reduce the heat to medium-low. Stir in the rice, making sure it's covered by liquid."},{"text":"Simmer, stirring occasionally, for about 20 minutes, until the rice is nearly tender and most of the liquid is absorbed."},{"text":"Gently fold in the prawns, crab, and oysters (if using). Cook for 3 to 4 minutes, until the prawns are pink and cooked through and the oysters have just firmed up."},{"text":"Season to taste with salt and pepper. Serve hot, scattered with fresh parsley if you like."}],"id":"14ca1271-d6df-47e0-a6c8-5cb39d61c636"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"notes":["Make sure your dosa batter is at room temperature; cold batter won't spread and cook evenly.","If your batter is too thick, add a splash of water, it should be pourable but thicker than a dosa batter.","Uttapam keeps for a day in an airtight container and reheats well in a toaster or griddle."],"steps":[{"text":"Heat a non-stick griddle or heavy-bottomed pan over medium heat and lightly oil it."},{"text":"Pour 1/4 cup of batter onto the griddle and gently spread into a thick round, about 8 cm across. Don't thin it out like a dosa, keep it thick and spongy."},{"text":"Let it cook, undisturbed, for about 2 minutes until the bottom is golden and set."},{"text":"Sprinkle a small handful of chopped onion, tomato, green chilli and coriander (if using) over the top. Press gently into the batter."},{"text":"Flip carefully and cook the other side for another 2 minutes until golden. If the top toppings aren't cooked enough, cover the pan with a lid for 30 seconds."},{"text":"Transfer to a plate and repeat with the remaining batter and toppings."},{"text":"Serve hot with sambar, rasam or fresh coconut chutney."}],"id":"788f0fca-b612-486d-a6ce-fed1f3c19960"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;